Certainly! Here's a robust TypeScript debounce utility with:

- **Preserved argument/return types**  
- **Cancellation support** (`cancel()` to clear a pending call)

```typescript
type DebouncedFunction<F extends (...args: any[]) => any> = {
  (...args: Parameters<F>): void;
  cancel: () => void;
};

/**
 * Debounce utility with cancellation and preserved types
 * @param func The function to debounce
 * @param wait Wait time in ms
 * @returns Debounced function with a .cancel() method
 */
export function debounce<F extends (...args: any[]) => any>(
  func: F,
  wait: number
): DebouncedFunction<F> {
  let timeout: ReturnType<typeof setTimeout> | undefined;

  const debounced = (...args: Parameters<F>): void => {
    if (timeout !== undefined) {
      clearTimeout(timeout);
    }
    timeout = setTimeout(() => {
      func(...args);
      timeout = undefined;
    }, wait);
  };

  debounced.cancel = () => {
    if (timeout !== undefined) {
      clearTimeout(timeout);
      timeout = undefined;
    }
  };

  return debounced;
}
```

**Usage Example:**

```typescript
const log = (n: number, msg: string) => {
  console.log(n, msg);
};

const debouncedLog = debounce(log, 500);

debouncedLog(123, 'Hello!');
debouncedLog.cancel(); // Cancels the pending call
```

- Argument types & parameter names are preserved by the utility.
- `debounced.cancel()` can be called at any time to clear any pending invocation.

